    public void show_context_menu(Control owner,Vector2 position,bool actorClicked,double timelineTime,int layer,string rootLabel,string sectionId)
    {
        var model=Model(owner);owner.Set("_context_on_actor",actorClicked);owner.Set("_context_section_id",sectionId);owner.Set("_context_time",timelineTime<0?Time(owner):timelineTime);owner.Set("_context_layer",layer<0?model.Get("selected_layer").AsInt32():layer);var menu=owner.Get("context_menu").As<PopupMenu>();menu.Clear();int count=model.Get("selected_ids").AsGodotArray().Count;var actor=_timeline.selected_actor(model);bool copied=owner.Get("_actor_clipboard").AsGodotArray().Count>0;if(actorClicked&&count>0&&actor!=null){menu.AddItem(count==1?actor.Get("display_name").AsString().ToUpperInvariant():$"{count} ACTORS SELECTED",100);menu.SetItemDisabled(menu.GetItemIndex(100),true);var definition=_definitions.get_definition(owner.Get("registry").As<RefCounted>(),actor.Get("type_id").AsStringName());var icon=definition?.Get("icon").As<Texture2D>();if(icon!=null)menu.SetItemIcon(menu.GetItemIndex(100),icon);menu.AddSeparator();bool current=actor.Get("id").AsString()==model.Get("focused_actor_id").AsString();menu.AddItem(current?"Go Up One Level  •  F":"Focus Actor  •  F",108);menu.SetItemTooltip(menu.GetItemIndex(108),current?"Return to the parent view":"Show only "+actor.Get("display_name").AsString()+" and its descendants");menu.AddItem("Duplicate",101);menu.AddItem("Copy",102);if(count==1&&actor.Get("type_id").AsString()=="audio")menu.AddItem("Edit in Audio Workspace",90721);menu.AddItem("Set Start / End…",109);if(copied)menu.AddItem(count==1?"Paste as Child":"Paste to Each as Child",103);if(count>1){menu.AddSeparator();menu.AddItem("Parent to "+actor.Get("display_name").AsString(),104);}bool parented=_timeline.selected_actors(model).Any(value=>value.As<Resource>().Get("parent_id").AsString().Length>0);menu.AddItem("Unparent",105);menu.SetItemDisabled(menu.GetItemIndex(105),!parented);menu.AddSeparator();menu.AddItem("Delete",106);}else{menu.AddItem(rootLabel.Length>0?rootLabel:$"TIMELINE  •  {owner.Get("_context_time").AsDouble():F1}s",100);menu.SetItemDisabled(menu.GetItemIndex(100),true);menu.AddSeparator();menu.AddItem($"{(rootLabel.Length>0?"Paste into Scene":"Paste at Playhead")}  •  {Time(owner):F2}s",103);menu.SetItemDisabled(menu.GetItemIndex(103),!copied);if(sectionId.Length>0){menu.AddSeparator();menu.AddItem("Delete Section…",107);}}menu.Position=new Vector2I((int)position.X,(int)position.Y);Hint(owner,menu,"Choose an action • Esc closes menu");menu.Popup();
    }
    public void context_action_selected(Control owner,int id){switch(id){case 90721:var tabs=owner.GetTree().GetFirstNodeInGroup("actor_scene_tabs");var actor=_timeline.selected_actor(Model(owner));if(tabs!=null&&actor!=null)tabs.Call("open_audio_actor",actor);break;case 101:duplicate_selected(owner);break;case 102:copy_selected(owner);break;case 103:paste_copied(owner,owner.Get("_context_on_actor").AsBool(),Time(owner),owner.Get("_context_layer").AsInt32());break;case 104:parent_selected(owner);break;case 105:unparent_selected(owner);break;case 106:delete_selected(owner);break;case 107:confirm_delete_section(owner,owner.Get("_context_section_id").AsString());break;case 108:focus_selected_actor(owner);break;case 109:refresh(owner);owner.Get("timing_dialog").As<AcceptDialog>().PopupCentered(new Vector2I(380,108));break;}}
